L162: void Application::Run() {
L163:     // Set the priority of the main task to 10
L164:     vTaskPrioritySet(nullptr, 10);
L165:     const EventBits_t ALL_EVENTS =
L166:         MAIN_EVENT_SCHEDULE | MAIN_EVENT_SEND_AUDIO | MAIN_EVENT_WAKE_WORD_DETECTED |
L167:         MAIN_EVENT_VAD_CHANGE | MAIN_EVENT_CLOCK_TICK | MAIN_EVENT_ERROR |
L168:         MAIN_EVENT_NETWORK_CONNECTED | MAIN_EVENT_NETWORK_DISCONNECTED | MAIN_EVENT_TOGGLE_CHAT |
L169:         MAIN_EVENT_START_LISTENING | MAIN_EVENT_STOP_LISTENING | MAIN_EVENT_ACTIVATION_DONE |
L170:         MAIN_EVENT_STATE_CHANGED | MAIN_EVENT_PLAYBACK_DRAINED;
L171:     while (true) {
L172:         auto bits = xEventGroupWaitBits(event_group_, ALL_EVENTS, pdTRUE, pdFALSE, portMAX_DELAY);
L173: 
L174:         if (bits & MAIN_EVENT_ERROR) {
L175:             if (GetDeviceState() == kDeviceStateNotifying) {
L176:                 StopNotification();
L177:             }
L178:             SetDeviceState(kDeviceStateIdle);
L179:             Alert(Lang::Strings::ERROR, last_error_message_.c_str(), "cancel",
L180:                   Lang::Sounds::OGG_EXCLAMATION);
L181:         }
L182:         if (bits & MAIN_EVENT_NETWORK_CONNECTED) {
L183:             HandleNetworkConnectedEvent();
L184:         }
L185: 
L186:         if (bits & MAIN_EVENT_NETWORK_DISCONNECTED) {
L187:             HandleNetworkDisconnectedEvent();
L188:         }
L189: 
L190:         if (bits & MAIN_EVENT_ACTIVATION_DONE) {
L191:             HandleActivationDoneEvent();
L192:         }
L193: 
L194:         if (bits & MAIN_EVENT_STATE_CHANGED) {
L195:             HandleStateChangedEvent();
L196:         }
L197:         if (bits & MAIN_EVENT_PLAYBACK_DRAINED) {
L198:             if (audio_service_.IsPlaybackIdle()) {
L199:                 notify_player_.OnPlaybackDrained();
L200:             }
L201:             // Deferred listening start (auto mode): the playback queue has
L202:             // drained, so it is now safe to enable voice processing.
L203:             if (pending_listening_start_ && GetDeviceState() == kDeviceStateListening &&
L204:                 audio_service_.IsPlaybackIdle()) {
L205:                 pending_listening_start_ = false;
L206:                 StartListeningAudio();
L207:             }
L208:         }
L209:         if (bits & MAIN_EVENT_TOGGLE_CHAT) {
L210:             HandleToggleChatEvent();
L211:         }
L212: 
L213:         if (bits & MAIN_EVENT_START_LISTENING) {
L214:             HandleStartListeningEvent();
L215:         }
L216: 
L217:         if (bits & MAIN_EVENT_STOP_LISTENING) {
L218:             HandleStopListeningEvent();
L219:         }
L220:         if (bits & MAIN_EVENT_SEND_AUDIO) {
L221:             while (auto packet = audio_service_.PopPacketFromSendQueue()) {
L222:                 if (protocol_ && !protocol_->SendAudio(std::move(packet))) {
L223:                     // Drop the remaining packets. Leaving them in the queue would
L224:                     // stall the Opus codec task (it waits for queue space), which in
L225:                     // turn deadlocks the whole audio input pipeline, as no new
L226:                     // MAIN_EVENT_SEND_AUDIO event would ever be triggered again.
L227:                     while (audio_service_.PopPacketFromSendQueue())
L228:                         ;
L229:                     break;
L230:                 }
L231:             }
L232:         }
L233:         if (bits & MAIN_EVENT_WAKE_WORD_DETECTED) {
L234:             HandleWakeWordDetectedEvent();
L235:         }
L236: 
L237:         if (bits & MAIN_EVENT_VAD_CHANGE) {
L238:             if (GetDeviceState() == kDeviceStateListening) {
L239:                 auto led = Board::GetInstance().GetLed();
L240:                 led->OnStateChanged();
L241:             }
L242:         }
L243:         if (bits & MAIN_EVENT_SCHEDULE) {
L244:             std::unique_lock<std::mutex> lock(mutex_);
L245:             auto tasks = std::move(main_tasks_);
L246:             lock.unlock();
L247:             for (auto& task : tasks) {
L248:                 task();
L249:             }
L250:         }
L251: 
L252:         if (bits & MAIN_EVENT_CLOCK_TICK) {
L253:             clock_ticks_++;
L254:             auto display = Board::GetInstance().GetDisplay();
L255:             display->UpdateStatusBar();
L256:             // Print debug info every 10 seconds
L257:             if (clock_ticks_ % 10 == 0) {
L258:                 SystemInfo::PrintHeapStats();
L259:                 // SystemInfo::PrintTaskList();
L260:                 // SystemInfo::PrintTaskCpuUsage(pdMS_TO_TICKS(1000));
L261:             }
L262:         }
L263:     }
L264: }
