L399: void Application::CheckNewVersion() {
L400:     const int MAX_RETRY = 10;
L401:     int retry_count = 0;
L402:     int retry_delay = 10;  // Initial retry delay in seconds
L403: 
L404:     auto& board = Board::GetInstance();
L405:     while (true) {
L406:         auto display = board.GetDisplay();
L407:         display->SetStatus(Lang::Strings::CHECKING_NEW_VERSION);
L408:         esp_err_t err = ota_->CheckVersion();
L409:         if (err != ESP_OK) {
L410:             retry_count++;
L411:             if (retry_count >= MAX_RETRY) {
L412:                 ESP_LOGE(TAG, "Too many retries, exit version check");
L413:                 return;
L414:             }
L415:             char error_message[128];
L416:             int error_message_length =
L417:                 snprintf(error_message, sizeof(error_message), "code=%d, url=%s", err,
L418:                          ota_->GetCheckVersionUrl().c_str());
L419:             if (error_message_length < 0 ||
L420:                 error_message_length >= static_cast<int>(sizeof(error_message))) {
L421:                 snprintf(error_message, sizeof(error_message), "code=%d", err);
L422:             }
L423:             char buffer[320];
L424:             int alert_message_length =
L425:                 snprintf(buffer, sizeof(buffer), Lang::Strings::CHECK_NEW_VERSION_FAILED,
L426:                          retry_delay, error_message);
L427:             if (alert_message_length < 0 ||
L428:                 alert_message_length >= static_cast<int>(sizeof(buffer))) {
L429:                 snprintf(buffer, sizeof(buffer), "code=%d", err);
L430:             }
L431:             Alert(Lang::Strings::ERROR, buffer, "cloud_off", Lang::Sounds::OGG_EXCLAMATION);
L432:             ESP_LOGW(TAG, "Check new version failed, retry in %d seconds (%d/%d)", retry_delay,
L433:                      retry_count, MAX_RETRY);
L434:             for (int i = 0; i < retry_delay; i++) {
L435:                 vTaskDelay(pdMS_TO_TICKS(1000));
L436:                 if (GetDeviceState() == kDeviceStateIdle) {
L437:                     break;
L438:                 }
L439:             }
L440:             retry_delay *= 2;  // Double the retry delay
L441:             continue;
L442:         }
L443:         retry_count = 0;
L444:         retry_delay = 10;  // Reset retry delay
L445:         if (ota_->HasNewVersion()) {
L446:             if (UpgradeFirmware(ota_->GetFirmwareUrl(), ota_->GetFirmwareVersion())) {
L447:                 return;  // This line will never be reached after reboot
L448:             }
