L451:         // No new version, mark the current version as valid
L452:         ota_->MarkCurrentVersionValid();
L453:         if (!ota_->HasActivationCode() && !ota_->HasActivationChallenge()) {
L454:             // Exit the loop if done checking new version
L455:             break;
L456:         }
L457:         display->SetStatus(Lang::Strings::ACTIVATION);
L458:         // Activation code is shown to the user and waiting for the user to input
L459:         if (ota_->HasActivationCode()) {
L460:             ShowActivationCode(ota_->GetActivationCode(), ota_->GetActivationMessage());
L461:         }
L462:         // This will block the loop until the activation is done or timeout
L463:         for (int i = 0; i < 10; ++i) {
L464:             ESP_LOGI(TAG, "Activating... %d/%d", i + 1, 10);
L465:             esp_err_t err = ota_->Activate();
L466:             if (err == ESP_OK) {
L467:                 break;
L468:             } else if (err == ESP_ERR_TIMEOUT) {
L469:                 vTaskDelay(pdMS_TO_TICKS(3000));
L470:             } else {
L471:                 vTaskDelay(pdMS_TO_TICKS(10000));
L472:             }
L473:             if (GetDeviceState() == kDeviceStateIdle) {
L474:                 break;
L475:             }
L476:         }
L477:     }
